		t.Fatalf("seed refresh token: %v", err)
	}

	c := &contexts.Context{Name: name, CoreURL: coreURL, Handle: "alice", KeychainService: svc}
	provider, err := NewRefreshingLoginProvider(c, transport, true)
	if err != nil {
